@@ -429,9 +429,13 @@ public abstract class BeanSerializerBase
             if (objectIdInfo == null) {
                 // no ObjectId override, but maybe ObjectIdRef?
                 if (oiw != null) {
-                    objectIdInfo = intr.findObjectReferenceInfo(accessor,
-                            new ObjectIdInfo(NAME_FOR_OBJECT_REF, null, null, null));
-                        oiw = _objectIdWriter.withAlwaysAsId(objectIdInfo.getAlwaysAsId());
+                    ObjectIdInfo refInfo = new ObjectIdInfo(NAME_FOR_OBJECT_REF, null, null, null);
+                    ObjectIdInfo origInfo = refInfo;
+                    refInfo = intr.findObjectReferenceInfo(accessor, refInfo);
+                    System.err.println("DEBUG: Field " + (accessor != null ? accessor.getName() : "?") + " has ObjectIdInfo: " + (objectIdInfo != null) + ", refInfo changed=" + (refInfo != origInfo));
+                    if (refInfo != origInfo) {
+                        oiw = _objectIdWriter.withAlwaysAsId(refInfo.getAlwaysAsId());
+                    }
                 }
             } else {
                 // Ugh: mostly copied from BeanDeserializerBase: but can't easily change it
@@ -577,14 +581,18 @@ public abstract class BeanSerializerBase
             boolean startEndObject) throws IOException
     {
         final ObjectIdWriter w = _objectIdWriter;
+        System.err.println("DEBUG: _serializeWithObjectId for " + bean.getClass().getSimpleName() + " with alwaysAsId=" + w.alwaysAsId);
         WritableObjectId objectId = provider.findObjectId(bean, w.generator);
         // If possible, write as id already
         if (objectId.writeAsId(gen, provider, w)) {
+            System.err.println("DEBUG: writeAsId returned true");
             return;
         }
         // If not, need to inject the id:
         Object id = objectId.generateId(bean);
+        System.err.println("DEBUG: generated id=" + id);
         if (w.alwaysAsId) {
+            System.err.println("DEBUG: serializing as ID only");
             w.serializer.serialize(id, gen, provider);
             return;
         }
